}

#root {
    width: 100%;
    max-width: 600px;
    padding: 20px;
}

.image-preview-container {
    background-color: var(--surface-color);
    border-radius: var(--border-radius);
    overflow: hidden;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
    display: flex;
