', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/modal-dialog--framework-react--style-dark/google/gemini-3-flash-preview__s4/app.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='const { useState, useRef, useEffect } = React;

const DeleteConfirmationDialog = ({ isOpen, onClose, onConfirm }) => {
    const dialogRef = useRef(null);

    useEffect(() => {
        const dialog = dialogRef.current;
        if (!dialog) return;

        if (isOpen) {
            // Check if already open to avoid errors
            if (!dialog.open) {
                dialog.showModal();
            }
        } else {
            if (dialog.open) {
                dialog.close();
            }
        }
    }, [isOpen]);

    // Handle the native dialog close event (e.g., when pressing Escape)
    useEffect(() => {
        const dialog = dialogRef.current;
        if (!dialog) return;

        const handleClose = () => {
            if (isOpen) {
                onClose();
            }
        };

        dialog.addEventListener('close', handleClose);
        return () => dialog.removeEventListener('close', handleClose);
    }, [isOpen, onClose]);

    return (
        <dialog 
            ref={dialogRef}
            role="alertdialog"
            aria-labelledby="dialog-title"
            aria-describedby="dialog-description"
        >
            <div className="dialog-content">
                <div className="dialog-header">
                    <h2 id="dialog-title">Delete image?</h2>
                </div>
                <div className="dialog-body">
                    <p id="dialog-description">
                        This will permanently remove the image from your library. This action cannot be undone.
                    </p>
                </div>
                <div className="dialog-actions">
                    <button 
                        type="button" 
                        className="btn-secondary" 
                        onClick={onClose}
                    >
                        Cancel
                    </button>
                    <button 
                        type="button" 
                        className="btn-destructive" 
                        onClick={onConfirm}
                    >
                        Delete
                    </button>
                </div>
            </div>
        </dialog>
    );
};

const ImagePreview = () => {
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [isDeleted, setIsDeleted] = useState(false);

    const handleDeleteClick = () => {
        setIsDialogOpen(true);
    };

    const handleCloseDialog = () => {
        setIsDialogOpen(false);
    };

    const handleConfirmDelete = () => {
        setIsDialogOpen(false);
        setIsDeleted(true);
        // In a real app, you'd trigger the actual deletion here
        console.log("Image deleted");
    };

    if (isDeleted) {
        return (
            <div className="image-preview-container" style={{ padding: '40px', textAlign: 'center' }}>
                <p>Image has been removed from your library.</p>
                <button 
                    className="btn-secondary" 
                    onClick={() => setIsDeleted(false)}
                >
                    Restore (Demo)
                </button>
            </div>
        );
    }

    return (
        <div className="image-preview-container">
            <img 
                src="https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1200&q=80" 
                alt="Beautiful landscape with mountains and a lake at sunset"
            />
            <div className="controls">
                <button 
                    type="button" 
                    className="trigger" 
                    onClick={handleDeleteClick}
                >
                    Delete Image
                </button>
            </div>

            <DeleteConfirmationDialog 
                isOpen={isDialogOpen} 
                onClose={handleCloseDialog} 
                onConfirm={handleConfirmDelete}
            />
        </div>
    );
};

const App = () => {
    return (
        <main id="main-content">
            <h1 style={{ textAlign: 'center', marginBottom: '40px', fontWeight: '300' }}>Library Preview</h1>
            <ImagePreview />
        </main>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
