const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  let browser;
  try {
    browser = await chromium.launch();
  } catch (e) {
    console.log('Chromium launch failed, installing...');
    const { execSync } = require('child_process');
    execSync('npx playwright install chromium >/dev/null 2>&1');
    browser = await chromium.launch();
  }

  const page = await browser.newPage();
  const htmlContent = fs.readFileSync('index.html', 'utf8');
  // Since we use external JS/CSS, we need to serve them or inject them.
  // For simplicity in this environment, I'll use a local file server approach or data URIs if possible.
  // Actually, I'll just set the content and use addScriptTag for local files if they are in the same dir.

  // To test the modal, we need to click the trigger.
  await page.goto('file://' + process.cwd() + '/index.html');
  await page.waitForLoadState('networkidle');

  // Inject axe
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Test 1: Initial state (dialog closed)
  const resultsClosed = await page.evaluate(async () => await axe.run());

  // Test 2: Dialog open
  await page.click('.trigger');
  // Wait for React to render and dialog to open
  await page.waitForSelector('dialog[open]');
  const resultsOpen = await page.evaluate(async () => await axe.run());

  await browser.close();

  const report = (r) => {
    const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = r.violations.filter(v => v.tags.includes('best-practice'));
    return { wcag: wcag.map(v => ({id: v.id, impact: v.impact, nodes: v.nodes.length})), bp: bp.map(v => ({id: v.id, nodes: v.nodes.length})) };
  };

  console.log(JSON.stringify({ closed: report(resultsClosed), open: report(resultsOpen) }, null, 2));
})().catch(err => {
  console.error(err);
  process.exit(1);
});
