const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Set content directly to avoid potential file protocol issues with CDNs if any
  const html = fs.readFileSync('index.html', 'utf8');
  await page.setContent(html, { waitUntil: 'networkidle' });

  // Also need to inject the CSS and JS content since setContent doesn't load local relative files
  const css = fs.readFileSync('style.css', 'utf8');
  await page.addStyleTag({ content: css });

  const js = fs.readFileSync('app.js', 'utf8');
  // Need to handle Babel if app.js is JSX.
  // Actually index.html uses <script type=\"text/babel\" src=\"app.js\"></script>
  // In our test, we should let the browser handle it if possible, but setContent might be tricky.

  // Let's try file:// with full path again but wait for the script to load
  await page.goto('file://' + process.cwd() + '/index.html');

  // Check if root has content
  const content = await page.innerHTML('#root');
